CREATE COLUMN TABLE "TEST_AP"."RCR2" ("RcurCode" NVARCHAR(8) NOT NULL , "ObjType" INTEGER CS_INT, "LogInstanc" INTEGER CS_INT DEFAULT 0, "LineNum" INTEGER CS_INT NOT NULL , "RefDocEntr" INTEGER CS_INT, "RefDocNum" INTEGER CS_INT, "ExtDocNum" NVARCHAR(100), "RefObjType" NVARCHAR(20), "IssueDate" LONGDATE CS_LONGDATE, "Remark" NVARCHAR(254), "CardCode" NVARCHAR(15), "Instance" SMALLINT CS_INT DEFAULT 0 NOT NULL , PRIMARY KEY ("RcurCode", "Instance", "LineNum")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE INDEX "RCR2_CODE" ON "TEST_AP"."RCR2" ( "RcurCode" ASC )